            score += 25.0;
        }

        // If this is the only bin that can fit the item, prioritize it highly
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Penalty for having too many open bins (fragmentation control)
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a significant penalty to encourage filling existing bins first.
    // We scale this penalty by the number of open bins to prevent excessive fragmentation.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.5);
    }

    // 2. Lookahead optimization: If the next item can fit perfectly or near-perfectly into the 
    // remaining space, reward this placement heavily.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff == 0 {
            score -= 35.0; // Perfect complementary fit
        } else if diff < 10 {
            score -= 15.0; // Near-perfect fit
        }
    }

    // 3. Penalty for creating "dead space": If the residual is too small to fit the smallest possible
    // item (assuming 10 as effective floor), it's often worse than leaving more space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Balance: If we have many open bins, penalize larger residuals to force consolidation.
    // If we have few open bins, allow larger residuals to accommodate future items.
    let balance_factor = (mean_residual - post_residual as f64) * (open_bins_count as f64 * 0.1);
    score += balance_factor;

    // 5. Criticality: If this is the only bin that can fit the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}
